     // Duplicate layout

     function duplicateLayout(element) {
          let $element = $(element);
          let questionType = $element.data("field");
          let dataId = $element.data("id");
          let $elementToCopy = null;

          const typeMappings = {
               'textbox': `#for_copy_sec${dataId}`,
               'textarea': `#for_copy_sec${dataId}`,
               'dropdown': `#for_copy_sec${dataId}`,
               'radio': `#for_copy_sec${dataId}`,
               'date-field': `#for_copy_sec${dataId}`,
               'pricebox': `#for_copy_sec${dataId}`,
               'number-field': `#for_copy_sec${dataId}`,
               'percentBox': `#for_copy_sec${dataId}`,
               'dropdown-link': `#for_copy_sec${dataId}`
          };

          if(typeMappings[questionType]){
               $elementToCopy = $(typeMappings[questionType]);
          }

          if($elementToCopy && $elementToCopy.length){
               let copiedHTML = $elementToCopy.prop("outerHTML");

               copiedHTML = copiedHTML
                    .replace(/data-is_new=".*?"/g, 'data-is_new="true"')
                    .replace(/data-id=".*?"/g, 'value="appended"');

               let $copiedElement = $($.parseHTML(copiedHTML));
               if (!$copiedElement.length) return;


               let $section = $element.closest(".add_qu_sec > div");
               if ($section.length) {
                    $section.after($copiedElement);
               } else {
                    $(".add_qu_sec").append($copiedElement);
               }

               $copiedElement[0].scrollIntoView({ behavior: "smooth", block: "start" });
               alert("Layout has been duplicated.");

               updateOrderIds();
          }
     }


     // Copy layout

     function copyLayout(element) {

          let $element = $(element);
          let questionType = $element.data("field");
          let dataId = $element.data("id");
          $(".copy-checkbox").css("display", "block");

          let $elementToCopy = null;

          const typeMappings = {
               'textbox': `#for_copy_sec${dataId}`,
               'textarea': `#for_copy_sec${dataId}`,
               'dropdown': `#for_copy_sec${dataId}`,
               'radio': `#for_copy_sec${dataId}`,
               'date-field': `#for_copy_sec${dataId}`,
               'pricebox': `#for_copy_sec${dataId}`,
               'number-field': `#for_copy_sec${dataId}`,
               'percentBox': `#for_copy_sec${dataId}`,
               'dropdown-link': `#for_copy_sec${dataId}`
          };

          if (typeMappings[questionType]) {
               $elementToCopy = $(typeMappings[questionType]);
          }

          if ($elementToCopy && $elementToCopy.length) {
               let copiedHTML = $elementToCopy.prop("outerHTML");

               copiedHTML = copiedHTML
                    .replace(/data-is_new=".*?"/g, 'data-is_new="true"')
                    .replace(/data-id=".*?"/g, 'value="appended"');

               localStorage.setItem("copiedHTML", copiedHTML);

               alert("Layout has been copied to your clipboard. You can now paste it anywhere.");
          }
     }

     function pasteAtCursor(element) {
          let copiedHTML = localStorage.getItem("copiedHTML");
          let copiedLayouts = localStorage.getItem("copiedLayouts");

          if (copiedHTML) {
               if (!element) {
                    console.error("No element provided for layout insertion.");
                    return;
               }

               let $clickedBtn = $(element);
               let $nearestSection = $clickedBtn.closest(".add_qu_sec > div");

               if ($nearestSection.length) {
                    $nearestSection.before(copiedHTML);
               } else {
                    $(".add_qu_sec").append(copiedHTML);
               }

               alert("Layout has been pasted.");
               updateOrderIds();
               localStorage.removeItem("copiedHTML");

          } else if (copiedLayouts) {
               let layouts = JSON.parse(copiedLayouts);

               if (!element) {
                    console.error("No element provided for layout insertion.");
                    return;
               }

               let $clickedBtn = $(element);
               let $nearestSection = $clickedBtn.closest(".add_qu_sec > div");

               if ($nearestSection.length) {
                    layouts.forEach(function (layoutHTML) {
                         $nearestSection.before(layoutHTML);
                    });
               } else {
                    layouts.forEach(function (layoutHTML) {
                         $(".add_qu_sec").append(layoutHTML);
                    });
               }

               alert("Copied layouts have been pasted.");
               updateOrderIds();
               localStorage.removeItem("copiedLayouts");

          } else {
               alert("Please copy a layout first.");
          }
     }

     // Update order ids

     function updateOrderIds(){
          let orderElements = document.querySelectorAll(".add_qu_sec [data-order_id]");

          orderElements.forEach((ol, index) => {
               ol.setAttribute("data-order_id", index + 1); // Assign sequential order
          });
     }

     function copySelectedLayout(element){
          let copiedLayouts = [];

          $('.copy-checkbox:checked').each(function () {
               let $checkbox = $(this);
               let dataId = $checkbox.data("id");
               let selector = `#for_copy_sec${dataId}`;
               let $element = $(selector);

               if ($element.length) {
                    let html = $element.prop("outerHTML")
                         .replace(/data-is_new=".*?"/g, 'data-is_new="true"')
                         .replace(/data-id=".*?"/g, 'value="appended"');
                    copiedLayouts.push(html);
               }
          });

          if (copiedLayouts.length > 0) {
               localStorage.setItem("copiedLayouts", JSON.stringify(copiedLayouts));
              // alert("Selected layouts have been copied.");
          }else {
               //alert("No layouts selected.");
          }
     }


     $(document).on('change', '.copy-checkbox',function() {
          copySelectedLayout();

     });

</script>

